<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Customer,ProductVariant,SalesOrder,SalesOrderItem,StockReservation,InventoryBalance}; use App\Services\{AuthorizationService,SalesDocumentService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class SalesOrderController { public function index(Request $r){$q=SalesOrder::where('tenant_id',app(TenantContext::class)->id())->with(['customer','items'])->latest();return response()->json(['data'=>$q->paginate(min($r->integer('per_page',25),100))]);} public function store(Request $r,AuthorizationService $a){$t=app(TenantContext::class)->id();abort_unless($a->allows($r->user(),$t,'sales.manage'),403);$d=$r->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','currency_id'=>'nullable|uuid','exchange_rate'=>'nullable|numeric|gt:0','customer_id'=>'required|uuid','items'=>'required|array|min:1','items.*.variant_id'=>'required|uuid','items.*.preferred_location_id'=>'nullable|uuid','items.*.ordered_quantity'=>'required|numeric|min:0.000001','items.*.unit_price'=>'required|numeric|min:0','items.*.discount_rate'=>'nullable|numeric|min:0|max:100','items.*.tax_rate'=>'nullable|numeric|min:0|max:100']);$this->assertScope($d,$t);abort_unless(Customer::where('tenant_id',$t)->whereKey($d['customer_id'])->exists(),404);$payload=$d;$payload['items']=array_map(fn($i)=>['variant_id'=>$i['variant_id'],'quantity'=>$i['ordered_quantity'],'unit_price'=>$i['unit_price'],'discount_rate'=>$i['discount_rate']??0,'tax_rate'=>$i['tax_rate']??0],$d['items']);$calc=app(\App\Services\SalesCalculationService::class);$lines=array_map(fn($i)=>$calc->line($i),$payload['items']);$totals=$calc->totals($lines);$rate=(string)($d['exchange_rate']??'1');$o=DB::transaction(function()use($d,$lines,$totals,$t,$r,$rate){$o=SalesOrder::create([...$totals,'tenant_id'=>$t,'company_id'=>$d['company_id'],'branch_id'=>$d['branch_id']??null,'currency_id'=>$d['currency_id']??null,'exchange_rate'=>$rate,'base_total'=>\App\Support\Decimal::mul((string)$totals['total'],$rate),'customer_id'=>$d['customer_id'],'created_by'=>$r->user()->id,'number'=>app(\App\Services\SalesNumberService::class)->next($t,'order')]);foreach($d['items'] as $k=>$i){abort_unless(ProductVariant::where('tenant_id',$t)->whereKey($i['variant_id'])->exists(),404);SalesOrderItem::create([...$lines[$k],'tenant_id'=>$t,'sales_order_id'=>$o->id,'variant_id'=>$i['variant_id'],'preferred_location_id'=>$i['preferred_location_id']??null,'ordered_quantity'=>$lines[$k]['quantity']]);}return $o->load('items');});return response()->json(['data'=>$o],201);} public function submit(Request $r,SalesOrder $order,SalesDocumentService $state){$this->own($order);abort_unless(app(AuthorizationService::class)->allows($r->user(),$order->tenant_id,'sales.manage',$order->company_id,$order->branch_id),403);$state->transition($order,'order','pending_approval',$r->user()->id);return response()->json(['data'=>$order->fresh()]);} public function approve(Request $r,SalesOrder $order,AuthorizationService $a,SalesDocumentService $state){$this->own($order);abort_unless($a->allows($r->user(),$order->tenant_id,'sales.approve',$order->company_id,$order->branch_id),403);DB::transaction(function()use($order,$state,$r){foreach($order->items()->lockForUpdate()->get() as $i){$location=$i->preferred_location_id;if(!$location)throw ValidationException::withMessages(['items'=>['Every order line needs a preferred stock location before approval.']]);$balance=InventoryBalance::where('tenant_id',$order->tenant_id)->where('variant_id',$i->variant_id)->where('location_id',$location)->lockForUpdate()->first();$available=$balance?->quantity?Decimal::sub((string)$balance->quantity,(string)$balance->reserved_quantity):'0';if(Decimal::compare($available,(string)$i->ordered_quantity)<0)throw ValidationException::withMessages(['stock'=>['Insufficient available stock for order approval.']]);if(!$balance)throw ValidationException::withMessages(['stock'=>['No inventory balance exists for the selected location.']]);$balance->update(['reserved_quantity'=>Decimal::add((string)$balance->reserved_quantity,(string)$i->ordered_quantity)]);StockReservation::create(['tenant_id'=>$order->tenant_id,'sales_order_id'=>$order->id,'sales_order_item_id'=>$i->id,'location_id'=>$location,'quantity'=>$i->ordered_quantity]);$i->update(['reserved_quantity'=>$i->ordered_quantity]);}$state->transition($order,'order','approved',$r->user()->id);});return response()->json(['data'=>$order->fresh('items')]);} private function assertScope(array $data,string $tenantId):void{abort_unless(\App\Models\Company::where('tenant_id',$tenantId)->whereKey($data['company_id'])->exists(),404);if(!empty($data['branch_id']))abort_unless(\App\Models\Branch::where('tenant_id',$tenantId)->whereKey($data['branch_id'])->where('company_id',$data['company_id'])->exists(),404);if(!empty($data['currency_id']))abort_unless(\App\Models\AccountingCurrency::where('tenant_id',$tenantId)->whereKey($data['currency_id'])->exists(),404);} private function own(SalesOrder $o):void{abort_unless($o->tenant_id===app(TenantContext::class)->id(),404);} }
